FUNCTION_BLOCK FB_S12
VAR_INPUT
    EStop_NC : BOOL;
    ResetBtn : BOOL;
    StartBtn : BOOL;
    DoorClosed : BOOL;
END_VAR
VAR_OUTPUT
    MachineRun : BOOL := FALSE;
    ShiftCount : UINT := UINT#0;
    AlarmLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ResetConfirmed : BOOL := FALSE;
    ResetBtnLast : BOOL := FALSE;
    StartBtnLast : BOOL := FALSE;
    ResetRise : BOOL := FALSE;
    StartRise : BOOL := FALSE;
    RunScans : UINT := UINT#0;
    InitialScans : UINT := UINT#0;
END_VAR

(*
    规约冲突报告：
    C10 要求首两个扫描周期 AlarmLamp = FALSE；
    控制要求 1 要求急停当周期 AlarmLamp = TRUE。
    若上电时急停有效，两者不能同时满足。本实现优先急停安全要求，
    保留此冲突供审查，不声称全部规约已经满足或经过验证。

    C10 的启动禁止窗口采用首两个调用周期。
    门关闭时才接受复位上升沿；复位和启动同周期时不启动。
    未运行期间保留不足一分钟的累计扫描数。
    UINT 计数达到上限后饱和，避免溢出回零。
*)

ResetRise := ResetBtn AND NOT ResetBtnLast;
StartRise := StartBtn AND NOT StartBtnLast;

(* 即使处于急停，也更新边沿记忆，避免松开急停后产生伪边沿。 *)
ResetBtnLast := ResetBtn;
StartBtnLast := StartBtn;

IF NOT EStop_NC THEN
    MachineRun := FALSE;
    ResetConfirmed := FALSE;
    AlarmLamp := TRUE;
    Status := WORD#16#8B01;

ELSIF NOT DoorClosed THEN
    MachineRun := FALSE;
    ResetConfirmed := FALSE;
    AlarmLamp := FALSE;
    Status := WORD#16#8B03;

ELSE
    AlarmLamp := FALSE;

    IF NOT ResetConfirmed THEN
        MachineRun := FALSE;
        IF ResetRise THEN
            ResetConfirmed := TRUE;
        END_IF;
    ELSE
        (* 此分支仅接受此前扫描已确认复位后的启动边沿。 *)
        IF StartRise AND (InitialScans >= UINT#2) THEN
            MachineRun := TRUE;
        END_IF;
    END_IF;

    IF ResetConfirmed THEN
        Status := WORD#16#0000;
    ELSE
        Status := WORD#16#8B02;
    END_IF;
END_IF;

(* 满足 C10 中首两个扫描周期禁止运行的部分。 *)
IF InitialScans < UINT#2 THEN
    MachineRun := FALSE;
    InitialScans := InitialScans + UINT#1;
END_IF;

(* 每次调用代表 20 ms，3000 个运行扫描累计为 60 s。 *)
IF MachineRun THEN
    IF RunScans >= UINT#2999 THEN
        RunScans := UINT#0;
        IF ShiftCount < UINT#65535 THEN
            ShiftCount := ShiftCount + UINT#1;
        END_IF;
    ELSE
        RunScans := RunScans + UINT#1;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
